    // mounting-rotation-propagation: batch-queued job stabs inherit the main
    // stab's mounting rotation via this helper.
    #[test]
    fn apply_inherited_mounting_rotation_sets_and_skips() {
        let stab = StabilizationManager::default();
        assert!(!apply_inherited_mounting_rotation(&stab, None, None));
        assert_eq!(stab.gyro.read().imu_transforms.imu_rotation_angles, None);
        assert_eq!(stab.gyro.read().imu_transforms.acc_rotation_angles, None);

        assert!(apply_inherited_mounting_rotation(
            &stab,
            Some([0.0, -90.0, 0.0]),
            Some([0.0, 45.0, 0.0])
        ));
        let gyro = stab.gyro.read();
        assert_eq!(
            gyro.imu_transforms.imu_rotation_angles,
            Some([0.0, -90.0, 0.0])
        );
        assert_eq!(
            gyro.imu_transforms.acc_rotation_angles,
            Some([0.0, 45.0, 0.0])
        );
    }

    // mounting-rotation-propagation: a mounting change overwrites every queued
    // stab, skipping ones already at the target value.
    #[test]
    fn apply_mounting_rotation_to_stabs_overwrites_and_skips_unchanged() {
        let stab_a = Arc::new(StabilizationManager::default());
        let stab_b = Arc::new(StabilizationManager::default());
        stab_b.set_imu_rotation(0.0, -90.0, 0.0);
        let stabs = vec![(1u32, stab_a.clone()), (2u32, stab_b.clone())];

        // stab_b already at target -> only stab_a updated.
        assert_eq!(apply_mounting_rotation_to_stabs(&stabs, 0.0, -90.0, 0.0), 1);
        assert_eq!(
            stab_a.gyro.read().imu_transforms.imu_rotation_angles,
            Some([0.0, -90.0, 0.0])
        );

        // Same value again -> full no-op.
        assert_eq!(apply_mounting_rotation_to_stabs(&stabs, 0.0, -90.0, 0.0), 0);

        // Back to top (all zero) -> clears both.
        assert_eq!(apply_mounting_rotation_to_stabs(&stabs, 0.0, 0.0, 0.0), 2);
        assert_eq!(stab_a.gyro.read().imu_transforms.imu_rotation_angles, None);
        assert_eq!(stab_b.gyro.read().imu_transforms.imu_rotation_angles, None);
    }

    // ---- mounting-rotation-home-value ----

    #[test]
    fn mounting_angles_to_option_normalizes_top_to_none() {
        // All-zero == top mounting, stored as None just like core does.
        assert_eq!(mounting_angles_to_option(0.0, 0.0, 0.0), None);
        assert_eq!(
            mounting_angles_to_option(0.0, 45.0, 0.0),
            Some([0.0, 45.0, 0.0])
        );
        assert_eq!(
            mounting_angles_to_option(0.0, 0.0, -90.0),
            Some([0.0, 0.0, -90.0])
        );
    }

    // Bare-video branch only: a top-equivalent home value must not produce any
    // set call on the freshly built job stab (byte-identical to the pre-change
    // behaviour, and equivalent anyway since a fresh stab is already top). A
    // non-zero acc rotation still comes through — it is not part of the mounting
    // home value. The .gyroflow branch does NOT share this rule: there the stab
    // carries the project's rotation and a top home value must flatten it, see
    // top_home_value_flattens_a_queued_projects_rotation.
    #[test]
    fn top_home_value_injects_nothing_into_a_fresh_job() {
        let stab = StabilizationManager::default();
        assert!(!apply_inherited_mounting_rotation(
            &stab,
            mounting_angles_to_option(0.0, 0.0, 0.0),
            None
        ));
        assert_eq!(stab.gyro.read().imu_transforms.imu_rotation_angles, None);

        // acc rotation is an independent (MotionData) setting and is unaffected.
        assert!(apply_inherited_mounting_rotation(
            &stab,
            None,
            Some([0.0, 45.0, 0.0])
        ));
        let gyro = stab.gyro.read();
        assert_eq!(gyro.imu_transforms.imu_rotation_angles, None);
        assert_eq!(
            gyro.imu_transforms.acc_rotation_angles,
            Some([0.0, 45.0, 0.0])
        );
    }

    // A queued .gyroflow project keeps no per-job mounting angle: whatever
    // gyro_source.rotation the import applied is replaced by the home value.
    #[test]
    fn home_value_overrides_a_queued_projects_own_rotation() {
        let stab = StabilizationManager::default();
        // What import_gyroflow_data would have applied from the project.
        stab.set_imu_rotation(0.0, 90.0, -90.0);

        let home = mounting_angles_to_option(0.0, 45.0, 0.0);
        assert!(apply_home_mounting_rotation_over_project(&stab, home, true));
        assert_eq!(
            stab.gyro.read().imu_transforms.imu_rotation_angles,
            Some([0.0, 45.0, 0.0])
        );

        // Already at the home value -> no redundant re-integration.
        assert!(!apply_home_mounting_rotation_over_project(&stab, home, true));
    }

    // "The queue only follows the home value" is unconditional: a top home value
    // flattens a project's own rotation too, otherwise that job would sit in the
    // queue with a mounting angle no other job has.
    #[test]
    fn top_home_value_flattens_a_queued_projects_rotation() {
        let stab = StabilizationManager::default();
        stab.set_imu_rotation(0.0, 180.0, 0.0);

        let home = mounting_angles_to_option(0.0, 0.0, 0.0);
        assert_eq!(home, None);
        assert!(apply_home_mounting_rotation_over_project(&stab, home, true));
        // set_imu_rotation(0,0,0) stores None — the project's rotation is gone.
        assert_eq!(stab.gyro.read().imu_transforms.imu_rotation_angles, None);

        // Already flat -> no redundant re-integration.
        assert!(!apply_home_mounting_rotation_over_project(&stab, home, true));
    }

    // The two kinds of "no home rotation" must stay distinguishable: an
    // unpushed snapshot (selector still loading) means "unknown", not "top", and
    // must leave the job exactly as the pre-change code did.
    #[test]
    fn unknown_home_value_leaves_a_queued_projects_rotation_untouched() {
        let stab = StabilizationManager::default();
        stab.set_imu_rotation(0.0, 180.0, 0.0);

        assert!(!apply_home_mounting_rotation_over_project(&stab, None, false));
        assert_eq!(
            stab.gyro.read().imu_transforms.imu_rotation_angles,
            Some([0.0, 180.0, 0.0])
        );

        // Same snapshot value, but now it is known to be the user's home value
        // -> the project's rotation is flattened after all.
        assert!(apply_home_mounting_rotation_over_project(&stab, None, true));
        assert_eq!(stab.gyro.read().imu_transforms.imu_rotation_angles, None);
    }

    // Structural guard: add_file must take the mounting angle from the home
    // snapshot, never from the main stabilizer. The main preview can be
    // borrowing a rotation from a loaded .gyroflow project, and reading it here
    // would silently leak that borrow into every job enqueued meanwhile — a
    // failure that is invisible in the UI.
    #[test]
    fn add_file_takes_mounting_rotation_from_the_home_snapshot() {
        let source = include_str!("render_queue.rs");
        let idx = source
            .find("pub fn add_file(")
            .expect("add_file must exist");
        let body_after = &source[idx + "pub fn add_file(".len()..];
        let body_end = body_after
            .find("\n    pub fn ")
            .unwrap_or(body_after.len());
        let body = &body_after[..body_end];
        assert!(
            body.contains("self.home_mounting_rotation"),
            "add_file must read the home mounting snapshot"
        );
        assert!(
            !body.contains("imu_rotation_angles"),
            "add_file must not read the main stab's current mounting rotation \
             (it may be borrowed from a loaded project)"
        );
        assert!(
            body.contains("apply_home_mounting_rotation_over_project("),
            "the .gyroflow enqueue branch must apply the home value on top of \
             the project's own rotation"
        );
    }

    // Structural guard: the home snapshot has no push channel of its own — it
    // is recorded inside apply_mounting_rotation_to_all, which QML only ever
    // calls with the home value. Dropping that line would leave add_file with a
    // permanently empty snapshot and no visible symptom.
    #[test]
    fn apply_mounting_rotation_to_all_records_the_home_snapshot() {
        let source = include_str!("render_queue.rs");
        let idx = source
            .find("pub fn apply_mounting_rotation_to_all(")
            .expect("apply_mounting_rotation_to_all must exist");
        let body_after = &source[idx + "pub fn apply_mounting_rotation_to_all(".len()..];
        let body_end = body_after
            .find("\n    pub fn ")
            .unwrap_or(body_after.len());
        let body = &body_after[..body_end];
        assert!(
            body.contains("self.home_mounting_rotation =")
                && body.contains("self.home_mounting_known = true"),
            "apply_mounting_rotation_to_all must record the home snapshot"
        );
    }

    #[test]
    fn pix_fmt_high_bit_depth_detection() {
        use ffmpeg_next::format::Pixel;
        // 8-bit formats: not high bit depth.
        assert!(!pix_fmt_is_high_bit_depth(Pixel::YUV420P));
        assert!(!pix_fmt_is_high_bit_depth(Pixel::NV12));
        // 10-bit formats: high bit depth.
        assert!(pix_fmt_is_high_bit_depth(Pixel::YUV420P10LE));
        assert!(pix_fmt_is_high_bit_depth(Pixel::P010LE));
        assert!(pix_fmt_is_high_bit_depth(Pixel::YUV422P10LE));
        assert!(pix_fmt_is_high_bit_depth(Pixel::YUV444P10LE));
        // 12-bit format: high bit depth.
        assert!(pix_fmt_is_high_bit_depth(Pixel::YUV420P12LE));
        // Undetermined (Pixel::None): safe default false → codec left untouched.
        assert!(!pix_fmt_is_high_bit_depth(Pixel::None));
    }

    // ---- amd-amf-encoder-capability-guard: bit-depth codec guard ----

    fn guard_opts(codec: &str, use_gpu: bool) -> RenderOptions {
        RenderOptions {
            codec: codec.to_string(),
            codec_options: "some-variant".to_string(),
            use_gpu,
            ..Default::default()
        }
    }

    #[test]
    fn bit_depth_guard_switches_high_bit_depth_h264_gpu_to_hevc() {
        use ffmpeg_next::format::Pixel;
        for fmt in [
            Pixel::YUV420P10LE,
            Pixel::P010LE,
            Pixel::YUV422P10LE,
            Pixel::YUV420P12LE,
            Pixel::YUV444P16LE,
        ] {
            let mut opts = guard_opts("H.264/AVC", true);
            assert!(
                normalize_render_options_for_bit_depth(&mut opts, Some(fmt), 1),
                "{fmt:?} must trigger the guard"
            );
            assert_eq!(opts.codec, "H.265/HEVC");
            // Codec-specific encoder options must not survive the switch.
            assert!(opts.codec_options.is_empty());
            // GPU encoding is retained on purpose (hevc_* encodes high bit depth).
            assert!(opts.use_gpu);
        }
    }

    #[test]
    fn bit_depth_guard_leaves_eight_bit_sources_alone() {
        use ffmpeg_next::format::Pixel;
        for fmt in [Pixel::YUV420P, Pixel::NV12] {
            let mut opts = guard_opts("H.264/AVC", true);
            assert!(!normalize_render_options_for_bit_depth(
                &mut opts,
                Some(fmt),
                1
            ));
            assert_eq!(opts.codec, "H.264/AVC");
            assert_eq!(opts.codec_options, "some-variant");
        }
    }

    #[test]
    fn bit_depth_guard_leaves_undetermined_bit_depth_alone() {
        use ffmpeg_next::format::Pixel;
        // Probe failed entirely (MDK-decoded sources) …
        let mut opts = guard_opts("H.264/AVC", true);
        assert!(!normalize_render_options_for_bit_depth(&mut opts, None, 1));
        assert_eq!(opts.codec, "H.264/AVC");
        // … or probed but with no usable pixel format.
        let mut opts = guard_opts("H.264/AVC", true);
        assert!(!normalize_render_options_for_bit_depth(
            &mut opts,
            Some(Pixel::None),
            1
        ));
        assert_eq!(opts.codec, "H.264/AVC");
    }

    #[test]
    fn bit_depth_guard_only_applies_to_h264_with_gpu() {
        use ffmpeg_next::format::Pixel;
        // CPU H.264 encodes 10-bit fine (libx264 High 10).
        let mut opts = guard_opts("H.264/AVC", false);
        assert!(!normalize_render_options_for_bit_depth(
            &mut opts,
            Some(Pixel::YUV420P10LE),
            1
        ));
        assert_eq!(opts.codec, "H.264/AVC");

        // Non-H.264 codecs are never touched, GPU or not.
        for codec in ["H.265/HEVC", "AV1", "ProRes", "DNxHD", "CineForm"] {
            let mut opts = guard_opts(codec, true);
            assert!(!normalize_render_options_for_bit_depth(
                &mut opts,
                Some(Pixel::YUV420P10LE),
                1
            ));
            assert_eq!(opts.codec, codec);
            assert_eq!(opts.codec_options, "some-variant");
        }
    }

    // Structural guard: the bit-depth guard must stay at the single Job
    // construction point. It previously lived in `add_file` only, which left the
    // main-preview add, `.gyroflow` project restore and apply-to-all paths
    // unguarded (two field reports). Moving it back to a single enqueue path
    // would silently reintroduce that gap, so pin the call site here.
    #[test]
    fn bit_depth_guard_is_called_from_add_internal() {
        let source = include_str!("render_queue.rs");
        let add_internal_idx = source
            .find("pub fn add_internal(")
            .expect("add_internal must exist");
        // Bound the search at the next `pub fn` after add_internal so a call in
        // some later function cannot satisfy this assertion by accident.
        let body_after = &source[add_internal_idx + "pub fn add_internal(".len()..];
        let body_end = body_after
            .find("\n    pub fn ")
            .unwrap_or(body_after.len());
        let body = &body_after[..body_end];
        assert!(
            body.contains("normalize_render_options_for_bit_depth("),
            "the bit-depth guard must run inside add_internal (the single Job \
             construction point), not on individual enqueue paths"
        );
    }

    // ---- plugin-only-export-gate ----

    #[test]
    fn plugin_only_extension_tiers_are_case_insensitive() {
        // Sibling-mov-exempt tier.
        assert!(RenderQueue::plugin_only_extension_unless_sibling_mov("AAA_2399.R3D"));
        assert!(RenderQueue::plugin_only_extension_unless_sibling_mov("aaa_2399.r3d"));
        assert!(RenderQueue::plugin_only_extension_unless_sibling_mov("clip.NEV"));
        assert!(RenderQueue::plugin_only_extension_unless_sibling_mov("clip.nev"));
        assert!(!RenderQueue::plugin_only_extension_unless_sibling_mov("clip.braw"));
        assert!(!RenderQueue::plugin_only_extension_unless_sibling_mov("clip.dng"));

        // Unconditional tier.
        assert!(RenderQueue::plugin_only_extension_always("Cam.braw"));
        assert!(RenderQueue::plugin_only_extension_always("CAM.BRAW"));
        assert!(RenderQueue::plugin_only_extension_always("raw.dng"));
        assert!(RenderQueue::plugin_only_extension_always("RAW.DNG"));
        // A collapsed image sequence keeps the extension on the pattern name.
        assert!(RenderQueue::plugin_only_extension_always("A001_%06d.dng"));
        assert!(!RenderQueue::plugin_only_extension_always("clip.r3d"));

        // Ordinary and other raw formats pass through untouched in both tiers.
        for name in ["clip.mp4", "clip.mov", "clip.mxf", "clip.crm", "r3d", "braw"] {
            assert!(!RenderQueue::plugin_only_extension_always(name), "{name}");
            assert!(
                !RenderQueue::plugin_only_extension_unless_sibling_mov(name),
                "{name}"
            );
        }
    }

    #[test]
    fn is_plugin_only_source_respects_sibling_mov() {
        let dir =
            std::env::temp_dir().join(format!("gf_plugin_only_test_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let r3d = dir.join("AAA_0001.R3D");
        std::fs::write(&r3d, b"x").unwrap();
        let url = filesystem::path_to_url(r3d.to_str().unwrap());

        // No sibling .mov -> plugin only.
        assert!(RenderQueue::is_plugin_only_source(&url));

        // Sibling same-name .mov -> legacy redirect path, not plugin only.
        let mov = dir.join("AAA_0001.mov");
        std::fs::write(&mov, b"x").unwrap();
        assert!(!RenderQueue::is_plugin_only_source(&url));

        // Ordinary formats never match regardless of siblings.
        let mp4 = dir.join("clip.mp4");
        std::fs::write(&mp4, b"x").unwrap();
        assert!(!RenderQueue::is_plugin_only_source(&filesystem::path_to_url(
            mp4.to_str().unwrap()
        )));

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn is_plugin_only_source_ignores_sibling_mov_for_braw_and_dng() {
        let dir = std::env::temp_dir().join(format!(
            "gf_plugin_only_always_test_{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).unwrap();

        for stem in ["Cam.braw", "raw.dng"] {
            let src = dir.join(stem);
            std::fs::write(&src, b"x").unwrap();
            let url = filesystem::path_to_url(src.to_str().unwrap());

            // Without a sibling .mov.
            assert!(RenderQueue::is_plugin_only_source(&url), "{stem}");

            // With a sibling .mov the verdict must be identical: these formats
            // have no render-time redirect, so the exemption must not apply.
            // Byte-identical results here also prove the unconditional tier
            // short-circuits before any filesystem lookup.
            let mov = dir.join(std::path::Path::new(stem).with_extension("mov"));
            std::fs::write(&mov, b"x").unwrap();
            assert!(RenderQueue::is_plugin_only_source(&url), "{stem} with .mov");
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn single_video_render_gate_does_not_inline_extension_literals() {
        let app_qml = include_str!("../ui/App.qml");

        // Scope the scan to the stretch between the render() entry and the
        // "not available for rendering" notice -- that is the plugin-only gate.
        // Anything after it (e.g. the legacy REDline notice) is out of scope and
        // still carries its own extension check.
        let start = app_qml
            .find("function render(): void {")
            .expect("App.qml must define renderBtn.render()");
        let end = start
            + app_qml[start..]
                .find("This format is not available for rendering")
                .expect("render() must keep the plugin-only notice");
        // Strip whole-line comments: the rationale comment above the gate names
        // the extensions on purpose, and only executable text is in scope here.
        let gate: String = app_qml[start..end]
            .lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n");

        assert!(
            gate.contains("render_queue.is_plugin_only_video("),
            "the single-video gate must delegate to is_plugin_only_video"
        );
        for literal in [".braw", ".dng", ".r3d", ".nev"] {
            assert!(
                !gate.contains(literal),
                "the single-video gate must not inline the {literal} literal -- the queue path \
                 and this path drifted apart once already; both must read one helper"
            );
        }
    }

    #[test]
    fn is_plugin_only_source_matches_dng_image_sequence_pattern() {
        // A collapsed DNG sequence is addressed by its `%0Nd` pattern; the
        // pattern filename still carries the extension, so the unconditional
        // tier matches it without touching the filesystem.
        let dir = std::env::temp_dir().join(format!("gf_plugin_only_seq_{}", std::process::id()));
        let pattern = dir.join("A001_%06d.dng");
        let url = filesystem::path_to_url(pattern.to_str().unwrap());
        assert!(RenderQueue::is_plugin_only_source(&url));
    }

    fn queue_with_lens_display_job(
        manual_edit: bool,
        config: niyien_lens_presets::LensGroupConfig,
        metadata: core::gyro_source::FileMetadata,
    ) -> RenderQueue {
        let stabilizer = Arc::new(StabilizationManager::default());
        stabilizer
            .lens_group_manual_edit
            .store(manual_edit, SeqCst);
        let mut configs = niyien_lens_presets::default_lens_group_configs();
        let lens_index = config.lens_index;
        configs[lens_index] = config;
        *stabilizer.lens_group_config.write() = configs;

        let base_lens_metadata = JobLensMetadataBackup::from_metadata(&metadata);
        let job_stab = Arc::new(StabilizationManager::default());
        {
            let mut gyro = job_stab.gyro.write();
            gyro.file_metadata = metadata.into();
        }

        let mut queue = RenderQueue::new(stabilizer);
        queue.jobs.insert(
            1,
            Job {
                queue_index: 0,
                render_options: RenderOptions::default(),
                base_render_output_size: None,
                original_output_size: (0, 0),
                auto_rotate: false,
                additional_data: String::new(),
                cancel_flag: Default::default(),
                render_epoch: Default::default(),
                project_data: None,
                last_finished_export_project: None,
                last_written_offsets: None,
                stab: Some(job_stab),
                base_lens_metadata: Some(base_lens_metadata),
                lens_group_config_override: None,
                lens_index_override: None,
                focal_length_override: None,
                lens_group_index: Some(0),
                video_created_at: None,
                plugin_only: false,
                original_video_rotation: 0.0,
            },
        );
        queue
    }

