    #[test]
    fn render_queue_start_batch_autosync_runs_unclassified_canon_builtin_gyro_jobs_through_sync() {
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        add_motion_to_job(&mut queue, 1, false);
        {
            let job = queue.jobs.get(&1).unwrap();
            let stab = job.stab.as_ref().unwrap();
            // Canon body with a built-in CNDM gyro that camera_db's
            // `builtin_gyro_offset` table does not classify. Unknown means "never
            // measured", not "aligned", so the job must go through a normal
            // auto-sync rather than being silently skipped — that silent skip is
            // the R50 V regression this change fixes.
            //
            // The model name is synthetic on purpose: an end-to-end assertion here
            // reads the real camera_db, and a name that can never appear in it is
            // the only way to keep the assertion stable across data updates. The
            // classified (`one_frame` / `none`) side is covered deterministically by
            // the `builtin_gyro_gate_*` tests, which inject the table directly.
            let gyro = stab.gyro.write();
            let mut fm = gyro.file_metadata.write();
            fm.keep_video_gyro = true;
            fm.detected_source = Some("Canon EOS NOT-A-REAL-BODY".to_string());
        }

        queue.pause_flag.store(true, SeqCst);
        queue.start_batch_autosync();

        assert_eq!(queue.export_project, 2);
        assert!(queue.batch_sync_job_ids.contains(&1));
    }

    #[test]
    fn load_gyro_data_keep_video_gyro_arbitration_respects_probe_bypass_flag() {
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        add_motion_to_job(&mut queue, 1, false);
        let stab = queue.jobs.get(&1).unwrap().stab.as_ref().unwrap().clone();
        stab.gyro.write().file_metadata.write().keep_video_gyro = true;

        let garbage = b"definitely not a telemetry file".to_vec();

        // Default options: the arbitration early-exit returns Ok without
        // parsing and leaves the built-in gyro untouched.
        let mut stream = std::io::Cursor::new(garbage.clone());
        let res = stab.load_gyro_data(
            &mut stream,
            garbage.len(),
            "file:///probe-test.bin",
            false,
            &Default::default(),
            |_| (),
            Default::default(),
        );
        assert!(res.is_ok(), "arbitration early-exit must stay silent: {res:?}");
        {
            let gyro = stab.gyro.read();
            let fm = gyro.file_metadata.read();
            assert!(fm.keep_video_gyro);
            assert_eq!(fm.raw_imu.len(), 1, "built-in gyro must stay untouched");
        }

        // bypass flag: the guard is skipped and the regular external-IMU load
        // path runs — the built-in metadata gets replaced and the garbage
        // stream fails to parse instead of being silently skipped.
        let mut stream = std::io::Cursor::new(garbage.clone());
        let res = stab.load_gyro_data(
            &mut stream,
            garbage.len(),
            "file:///probe-test.bin",
            false,
            &core::gyro_source::FileLoadOptions {
                bypass_builtin_gyro_arbitration: true,
                ..Default::default()
            },
            |_| (),
            Default::default(),
        );
        assert!(res.is_err(), "bypass must reach the parse path (garbage -> Err)");
        {
            let gyro = stab.gyro.read();
            let fm = gyro.file_metadata.read();
            assert!(
                !fm.keep_video_gyro,
                "load path must have reset the pre-probe metadata"
            );
        }
    }

    // The deep-match collector is a single global slot; serialize the tests
    // that arm/take it.
    static DEEP_MATCH_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn deep_match_stats(
        ratio: f64,
    ) -> gyroflow_core::synchronization::deep_match::DeepMatchSegStats {
        gyroflow_core::synchronization::deep_match::DeepMatchSegStats {
            range_idx: 0,
            offset_ms: 0.0,
            cost_min: ratio * 100.0,
            cost_p25: 100.0,
            max_angle: 10.0,
        }
    }

    // Job 1 with a small "built-in" gyro; keep=true marks it as the trusted
    // motion source (Komodo/Sony/Canon material).
    fn setup_deep_match_job(queue: &mut RenderQueue, keep: bool) -> Arc<StabilizationManager> {
        add_motion_to_job(queue, 1, false);
        let stab = queue.jobs.get(&1).unwrap().stab.as_ref().unwrap().clone();
        stab.gyro.write().file_url = "file:///builtin-source.mp4".into();
        stab.gyro.write().file_metadata.write().keep_video_gyro = keep;
        queue.jobs.get_mut(&1).unwrap().additional_data = r#"{"original":true}"#.to_string();
        stab
    }

    // Registers the pending state (snapshots included) and simulates what the
    // probe run does to the live stores: the .bin gyro replaces the built-in
    // one, the one-shot sync params and an injected probe lens overwrite the
    // lens stores.
    fn simulate_deep_match_probe(queue: &mut RenderQueue, stab: &Arc<StabilizationManager>) {
        simulate_deep_match_probe_chunks(queue, stab, vec![(0.0, 7_200_000.0)], 0);
    }

    // Variant with an explicit chunk plan / position for chunked-scan tests.
    fn simulate_deep_match_probe_chunks(
        queue: &mut RenderQueue,
        stab: &Arc<StabilizationManager>,
        chunk_plan: Vec<(f64, f64)>,
        current_chunk: usize,
    ) {
        // A pool entry so a chunk advance can resolve the gyro path.
        queue.gyro_files = vec![GyroFileInfo {
            path: "file:///pool.bin".to_string(),
            filename: "pool.bin".to_string(),
            parsed: true,
            ..Default::default()
        }];
        let mut state = {
            let job = queue.jobs.get(&1).unwrap();
            RenderQueue::snapshot_deep_match_state(job, stab, 0, None)
        };
        state.chunk_plan = chunk_plan;
        state.current_chunk = current_chunk;
        queue.deep_match_pending.insert(1, state);
        {
            let mut md = FileMetadata::default();
            for i in 0..3 {
                md.raw_imu.push(core::gyro_source::TimeIMU {
                    timestamp_ms: i as f64 * 10.0,
                    gyro: Some([0.0, 0.0, 0.0]),
                    accl: None,
                    magn: None,
                });
            }
            let mut gyro = stab.gyro.write();
            gyro.load_from_telemetry(md);
            gyro.file_url = "file:///pool.bin".into();
        }
        let mut lens = stab.lens.write();
        lens.name = "PROBE-INJECTED".into();
        lens.sync_settings = Some(serde_json::json!({ "offset_method": 0, "one_shot": true }));
    }

    #[test]
    fn deep_match_success_restores_builtin_gyro_for_keep_material() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, true);
        simulate_deep_match_probe(&mut queue, &stab);

        deep_match::arm(2);
        deep_match::record(deep_match_stats(0.1));
        deep_match::record(deep_match_stats(0.2));
        queue.record_batch_sync_result(
            1,
            vec![
                sync_candidate(1, 1000.0, -5000.0, 0.9),
                sync_candidate(1, 2000.0, -5001.0, 0.9),
            ],
            vec![],
        );

        assert!(queue.deep_match_results.contains_key(&1), "expected Accepted");
        {
            let gyro = stab.gyro.read();
            let fm = gyro.file_metadata.read();
            assert!(fm.keep_video_gyro, "built-in gyro must be restored on keep material");
            assert_eq!(fm.raw_imu.len(), 1);
            assert_eq!(gyro.file_url, "file:///builtin-source.mp4");
        }
        let lens = stab.lens.read();
        assert_eq!(lens.name, "", "probe-injected lens must not leak");
        let ss = lens.sync_settings.clone().unwrap();
        assert_eq!(ss["offset_method"], 2);
        assert!((ss["initial_offset"].as_f64().unwrap() - (-5.0005)).abs() < 1e-9);
        let ad: serde_json::Value =
            serde_json::from_str(&queue.jobs[&1].additional_data).unwrap();
        assert_eq!(ad["original"], true);
        assert!(
            (ad["synchronization"]["initial_offset"].as_f64().unwrap() - (-5.0005)).abs() < 1e-9
        );
    }

    #[test]
    fn deep_match_success_keeps_bin_for_regular_material() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, false);
        simulate_deep_match_probe(&mut queue, &stab);

        deep_match::arm(2);
        deep_match::record(deep_match_stats(0.1));
        deep_match::record(deep_match_stats(0.2));
        queue.record_batch_sync_result(
            1,
            vec![
                sync_candidate(1, 1000.0, -5000.0, 0.9),
                sync_candidate(1, 2000.0, -5001.0, 0.9),
            ],
            vec![],
        );

        assert!(queue.deep_match_results.contains_key(&1), "expected Accepted");
        let gyro = stab.gyro.read();
        let fm = gyro.file_metadata.read();
        assert!(!fm.keep_video_gyro);
        assert_eq!(fm.raw_imu.len(), 3, "the .bin must stay loaded on regular material");
        assert_eq!(gyro.file_url, "file:///pool.bin");
    }

    // ---- pool-wide search + prelocation (deep-match-gyro-pool-prelocate) ----

    // Turns the simulated single-file run into a 2-probe pool plan over two
    // pool files (the second focused), so the advance path can be exercised.
    fn make_pool_plan(queue: &mut RenderQueue) {
        use gyroflow_core::synchronization::deep_match::ProbeTask;
        queue.gyro_files.push(GyroFileInfo {
            path: "file:///pool2.bin".to_string(),
            filename: "pool2.bin".to_string(),
            parsed: true,
            duration_ms: Some(14_400_000.0),
            ..Default::default()
        });
        let state = queue.deep_match_pending.get_mut(&1).unwrap();
        state.probe_plan = vec![
            ProbeTask { gyro_index: 0, tier: 1, window_ms: None },
            ProbeTask { gyro_index: 1, tier: 3, window_ms: Some((3_600_000.0, 10_800_000.0)) },
        ];
        state.current_probe = 0;
        state.pool_run = true;
    }

    #[test]
    fn deep_match_pool_rejection_advances_to_next_probe() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, false);
        simulate_deep_match_probe(&mut queue, &stab);
        make_pool_plan(&mut queue);

        // Widely-spread offsets -> Inconsistent -> probe 0 (single chunk)
        // exhausts -> the plan advances to probe 1 instead of terminating.
        deep_match::arm(2);
        deep_match::record(deep_match_stats(0.1));
        deep_match::record(deep_match_stats(0.1));
        queue.record_batch_sync_result(
            1,
            vec![
                sync_candidate(1, 1000.0, -5000.0, 0.9),
                sync_candidate(1, 2000.0, 5000.0, 0.9),
            ],
            vec![],
        );

        let state = queue.deep_match_pending.get(&1).expect("pool run must stay pending");
        assert_eq!(state.current_probe, 1);
        assert_eq!(state.gyro_index, 1, "gyro_index must track the current probe");
        assert_eq!(state.current_chunk, 0);
        assert!(
            (state.chunk_plan[0].0 - 3_600_000.0).abs() < 1e-9,
            "focused probe chunks must stay file-relative: {:?}",
            state.chunk_plan
        );
        assert!(queue.deep_match_results.is_empty());
        // Cleanup: drop the pending state so later tests are unaffected.
        queue.deep_match_pending.remove(&1);
    }

    #[test]
    fn deep_match_video_side_failure_terminates_whole_pool_plan() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, false);
        simulate_deep_match_probe(&mut queue, &stab);
        make_pool_plan(&mut queue);

        // A single window -> TooFewWindows (video-side motion gate) must
        // terminate the WHOLE plan: the video cannot match any gyro.
        deep_match::arm(2);
        deep_match::record(deep_match_stats(0.1));
        queue.record_batch_sync_result(1, vec![sync_candidate(1, 1000.0, -5000.0, 0.9)], vec![]);

        assert!(queue.deep_match_pending.is_empty(), "plan must terminate, not advance");
        assert!(queue.deep_match_results.is_empty());
        assert_eq!(queue.learned_clock_shift_ms, None);
    }

    #[test]
    fn deep_match_accept_learns_clock_shift_and_pairing_resets_clear_it() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, false);
        simulate_deep_match_probe(&mut queue, &stab);
        queue.gyro_files[0].created_at_ms = Some(1_000_000);
        stab.params.write().video_created_at = Some(2_000_000);

        deep_match::arm(2);
        deep_match::record(deep_match_stats(0.1));
        deep_match::record(deep_match_stats(0.2));
        queue.record_batch_sync_result(
            1,
            vec![
                sync_candidate(1, 1000.0, -5000.0, 0.9),
                sync_candidate(1, 2000.0, -5001.0, 0.9),
            ],
            vec![],
        );
        assert!(queue.deep_match_results.contains_key(&1), "expected Accepted");
        // offset = median(-5000, -5001) = -5000.5; learned shift =
        // gyro_created + round(5000.5) - video_created (the derive contract).
        let expected = 1_000_000 + 5001 - 2_000_000;
        assert_eq!(queue.learned_clock_shift_ms, Some(expected));
        // The day the shift was learned from is recorded alongside it.
        assert_eq!(
            queue.learned_clock_shift_day,
            RenderQueue::local_day_from_ms(2_000_000)
        );
        assert!(queue.learned_clock_shift_day.is_some());

        // Right-click "Unpair gyro" rejects the pairing -> what it taught
        // goes too.
        queue.unpair_video(1);
        assert_eq!(queue.learned_clock_shift_ms, None);
        assert_eq!(queue.learned_clock_shift_day, None);

        // Same for the global reset.
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(2_000_000);
        queue.reset_all_video_pairings();
        assert_eq!(queue.learned_clock_shift_ms, None);
        assert_eq!(queue.learned_clock_shift_day, None);
    }

    #[test]
    fn deep_match_cancel_in_progress_keeps_learned_shift() {
        use gyroflow_core::synchronization::deep_match;
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let stab = setup_deep_match_job(&mut queue, false);
        simulate_deep_match_probe(&mut queue, &stab);
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(2_000_000);

        // Cancelling a run that has not accepted anything learned nothing and
        // rejected nothing — the previously learned shift stays.
        queue.jobs.get(&1).unwrap().cancel_flag.store(true, SeqCst);
        deep_match::arm(2);
        queue.record_batch_sync_result(1, vec![], vec![]);

        assert!(queue.deep_match_pending.is_empty());
        assert_eq!(queue.learned_clock_shift_ms, Some(42));
        assert_eq!(
            queue.learned_clock_shift_day,
            RenderQueue::local_day_from_ms(2_000_000)
        );
    }

    #[test]
    fn deep_match_redundant_for_job_same_day_semantics() {
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        // Timezone-robust anchors: identical instants are trivially the same
        // local day; instants two full days apart can never share one.
        const DAY_MS: i64 = 86_400_000;
        let t = 10 * DAY_MS + 3_600_000;

        // No learned day yet -> false regardless of the job timestamp.
        queue.jobs.get_mut(&1).unwrap().video_created_at = Some(t);
        assert!(!queue.deep_match_redundant_for_job(1));

        // Learned day equals the job's local day -> true.
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(t);
        assert!(queue.deep_match_redundant_for_job(1));

        // Cross-day (two full days apart) -> false.
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(t + 2 * DAY_MS);
        assert!(!queue.deep_match_redundant_for_job(1));

        // Job without a creation time -> false (fail open).
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(t);
        queue.jobs.get_mut(&1).unwrap().video_created_at = None;
        assert!(!queue.deep_match_redundant_for_job(1));

        // Unknown job id -> false.
        assert!(!queue.deep_match_redundant_for_job(999));
    }

    #[test]
    fn clear_queue_clears_learned_clock_shift() {
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(2_000_000);

        // "Clear render queue" empties the queue -> the session learned shift
        // (and its same-day soft-intercept) is wiped with the batch.
        queue.clear();
        assert_eq!(queue.queue.borrow().row_count(), 0);
        assert_eq!(queue.learned_clock_shift_ms, None);
        assert_eq!(queue.learned_clock_shift_day, None);
    }

    #[test]
    fn individual_job_removal_keeps_learned_clock_shift() {
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        add_eta_job(&mut queue, 2, 1);
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(2_000_000);

        // Removing jobs one by one is NOT the clear action -> learned shift stays,
        // even once the last removal leaves the queue empty (the removal asymmetry).
        queue.remove(1);
        queue.remove(2);
        assert_eq!(queue.queue.borrow().row_count(), 0);
        assert_eq!(queue.learned_clock_shift_ms, Some(42));
        assert!(queue.learned_clock_shift_day.is_some());
    }

    #[test]
    fn stop_and_clear_clears_learned_shift_and_leaves_clean_state() {
        let _guard = DEEP_MATCH_TEST_LOCK.lock().unwrap();
        let mut queue = queue_with_eta_job(JobStatus::Rendering);
        queue.learned_clock_shift_ms = Some(42);
        queue.learned_clock_shift_day = RenderQueue::local_day_from_ms(2_000_000);
        // Prove stop() drops any paused state on the way to a clean stopped queue.
        queue.pause_flag.store(true, SeqCst);

        // With a job Rendering, a bare clear() cannot empty the queue; stop_and_clear
        // stops first (Rendering -> Queued), so clear() empties it and the learned
        // shift is cleared. pause_flag ends up false (clean stopped state).
        queue.stop_and_clear();
        assert_eq!(queue.queue.borrow().row_count(), 0);
        assert_eq!(queue.learned_clock_shift_ms, None);
        assert_eq!(queue.learned_clock_shift_day, None);
        assert!(!queue.pause_flag.load(SeqCst));
    }

    #[test]
    fn clear_emits_queue_cleared_in_the_empty_branch_only() {
        // Structural guard: queue_cleared() must be emitted from clear()'s
        // row_count()==0 branch, right next to clear_learned_clock_shift
        // ("fresh start" semantics share one point), and nowhere earlier.
        let source = include_str!("render_queue.rs");
        let fn_idx = source.find("pub fn clear(&mut self)").expect("clear() exists");
        let body = &source[fn_idx..];
        let end_idx = body
            .find("pub fn stop_and_clear")
            .expect("clear() ends before stop_and_clear");
        let body = &body[..end_idx];
        let branch_idx = body
            .find("row_count() == 0")
            .expect("clear() keeps the empty-queue branch");
        let shift_idx = body
            .find("clear_learned_clock_shift(\"clear_queue\")")
            .expect("clear() keeps the learned-shift clearing point");
        let signal_idx = body
            .find("self.queue_cleared()")
            .expect("clear() must emit queue_cleared for the export panel reset");
        assert!(
            branch_idx < shift_idx && shift_idx < signal_idx,
            "queue_cleared must be emitted inside the empty-queue branch, after clear_learned_clock_shift"
        );
    }

    #[test]
    fn batch_add_derives_per_source_output_defaults() {
        let qml = include_str!("../ui/RenderQueue.qml");
        let fn_idx = qml
            .find("function prepareBatchAdditionalData(")
            .expect("prepareBatchAdditionalData exists");
        let body = &qml[fn_idx..];
        let end_idx = body
            .find("function add(outFolder")
            .expect("prepareBatchAdditionalData ends before dt.add");
        let body = &body[..end_idx];

        assert!(
            body.contains("!window.exportSettings.isPreserveActive()"),
            "batch add must key the scrub on isPreserveActive (checkbox AND full mode)"
        );
        assert!(
            !body.contains("preserveOutputSettings.checked"),
            "batch add must not read the raw checkbox — ghost settings values would exempt Simple mode"
        );
        assert!(
            body.contains("delete additional.output.output_width")
                && body.contains("delete additional.output.output_height")
                && body.contains("delete additional.output.bitrate"),
            "batch add must drop size AND bitrate so jobs derive them from their own source"
        );
    }

    #[test]
    fn queue_cleared_resets_export_panel_in_qml() {
        let app_qml = include_str!("../ui/App.qml");
        let export_qml = include_str!("../ui/menu/Export.qml");

        assert!(
            app_qml.contains("function onQueue_cleared()")
                && app_qml.contains("resetToSourceDefaults()")
                && app_qml.contains("!window.exportSettings.isPreserveActive()"),
            "App.qml must reset the export panel on queue_cleared unless preserve is active (checkbox AND full mode)"
        );
        assert!(
            export_qml.contains("function resetToSourceDefaults()")
                && export_qml.contains("root.sourceBitrate = br;"),
            "Export.qml must record the source bitrate and offer resetToSourceDefaults"
        );
        assert!(
            export_qml.contains(
                "function isPreserveActive(): bool { return preserveOutputSettings.checked && !window.isSimpleMode; }"
            ),
            "isPreserveActive must gate on full mode so ghost preserveOutputSettings values \
             (e.g. historically migrated from an upstream Gyroflow settings.json) stay inert in Simple mode"
        );
    }

    #[test]
    fn preserve_path_is_inert_in_simple_mode() {
        let app_qml = include_str!("../ui/App.qml");
        let video_area_qml = include_str!("../ui/VideoArea.qml");
        let export_qml = include_str!("../ui/menu/Export.qml");

        assert!(
            export_qml.contains(
                "function isPreservePathActive(): bool { return preserveOutputPath.checked && !window.isSimpleMode; }"
            ),
            "isPreservePathActive must gate on full mode so a ghost preserveOutputPath \
             value cannot redirect Simple-mode output folders"
        );
        assert!(
            video_area_qml.contains("isPreservePathActive()")
                && !video_area_qml.contains("preserveOutputPath.checked"),
            "VideoArea must consult isPreservePathActive, not the raw checkbox"
        );
        assert!(
            app_qml.contains("isPreservePathActive()")
                && !app_qml.contains("preserveOutputPath.checked"),
            "App.qml preservedOutputPath write-back must consult isPreservePathActive — \
             the handler still fires in Simple mode even though its parent label is hidden"
        );
    }

