    #[test]
    fn reset_all_video_pairings_clears_registries() {
        // Video job 1 with live stab + motion + all three pairing registries set.
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        add_motion_to_job(&mut queue, 1, false);

        queue.manual_pairs.push(core::gyro_match::ManualCalibrationPair {
            job_id: 1,
            video_index: 0,
            gyro_index: 0,
        });
        queue.deep_match_results.insert(
            1,
            DeepMatchResult {
                gyro_index: 0,
                offset_ms: 12.0,
            },
        );
        // One matched video entry plus a calibration-pair entry: the reset must
        // clear both (D2) by wiping match_results entirely.
        queue.match_results = Some(core::gyro_match::BatchMatchResult {
            results: vec![
                core::gyro_match::MatchResult {
                    video_index: 0,
                    job_id: Some(1),
                    gyro_index: Some(0),
                    status: core::gyro_match::MatchStatus::Matched,
                    global_offset_ms: None,
                    gyro_start_ms: Some(100.0),
                    gyro_end_ms: Some(200.0),
                    init_offset_ms: None,
                },
                core::gyro_match::MatchResult {
                    video_index: 1,
                    job_id: Some(2),
                    gyro_index: None,
                    status: core::gyro_match::MatchStatus::CalibrationPair,
                    global_offset_ms: None,
                    gyro_start_ms: None,
                    gyro_end_ms: None,
                    init_offset_ms: None,
                },
            ],
            global_offset_ms: None,
            error: None,
        });

        queue.reset_all_video_pairings();

        // [reset-pairing-restore-just-loaded-state] All match state cleared to the
        // just-loaded baseline: registries empty and match_results == None, so
        // has_match_results() is false and the gyro column returns to preview mode.
        // The calibration-pair entry is gone along with the matched entry (D2).
        assert!(queue.manual_pairs.is_empty());
        assert!(queue.deep_match_results.is_empty());
        assert!(queue.match_results.is_none());
        assert!(!queue.has_match_results());

        // stab.gyro must NOT be cleared — its motion survives the reset (D5).
        let stab = queue.jobs.get(&1).unwrap().stab.as_ref().unwrap().clone();
        let gyro = stab.gyro.read();
        let file_metadata = gyro.file_metadata.read();
        assert!(!gyro.raw_imu(&file_metadata).is_empty());
    }

    #[test]
    fn batch_update_params_updates_live_stab_and_display_params() {
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let (stab, render_options) = {
            let job = queue.jobs.get(&1).unwrap();
            (job.stab.as_ref().unwrap().clone(), job.render_options.clone())
        };

        let project_data = RenderQueue::get_gyroflow_data_internal(
            &stab,
            "{}",
            &render_options,
        )
        .expect("project data export succeeds");

        {
            let job = queue.jobs.get_mut(&1).unwrap();
            job.project_data = Some(project_data);
        }

        queue.batch_update_params(
            serde_json::json!([1]).to_string(),
            serde_json::json!({
                "smoothness": 0.8,
                "horizon_lock_amount": 75.0,
                "zoom_mode": "static",
                "lens_correction": 0.25,
                "framerate": 25.0,
            })
            .to_string(),
        );

        let display = serde_json::from_str::<serde_json::Value>(
            &queue.get_job_display_params(1).to_string(),
        )
        .expect("display params parse");
        assert_eq!(display["smoothness"].as_f64(), Some(0.8));
        assert_eq!(display["horizon_lock_amount"].as_f64(), Some(75.0));
        assert_eq!(display["zoom_mode"].as_str(), Some("static"));
        assert_eq!(display["lens_correction"].as_f64(), Some(0.25));
        assert_eq!(display["source_fps"].as_f64(), Some(10.0));
        assert_eq!(display["framerate"].as_f64(), Some(25.0));

        let job = queue.jobs.get(&1).unwrap();
        let stab = job.stab.as_ref().unwrap();
        let live_data = serde_json::from_str::<serde_json::Value>(
            &stab
                .export_gyroflow_data(core::GyroflowProjectType::Simple, "{}", None)
                .expect("live stab export succeeds"),
        )
        .expect("live stab export parses");
        assert_eq!(smoothing_param_value(&live_data, "smoothness"), Some(0.8));
        assert_eq!(
            live_data["stabilization"]["horizon_lock_amount"].as_f64(),
            Some(75.0)
        );
        assert_eq!(
            live_data["stabilization"]["adaptive_zoom_window"].as_f64(),
            Some(-1.0)
        );
        assert_eq!(
            live_data["stabilization"]["lens_correction_amount"].as_f64(),
            Some(0.25)
        );
        assert_eq!(live_data["video_info"]["vfr_fps"].as_f64(), Some(25.0));
    }

    #[test]
    fn display_params_omit_stab_keys_for_reference_form_project_data() {
        let mut queue = queue_with_eta_job(JobStatus::Queued);
        let (stab, render_options) = {
            let job = queue.jobs.get(&1).unwrap();
            (job.stab.as_ref().unwrap().clone(), job.render_options.clone())
        };

        // Control: full project data exposes the stabilization-derived keys.
        stab.set_adaptive_zoom(-1.0);
        let full_data = RenderQueue::get_gyroflow_data_internal_with_type(
            &stab,
            "{}",
            &render_options,
            core::GyroflowProjectType::Simple,
            false,
        )
        .expect("project data export succeeds");
        queue.jobs.get_mut(&1).unwrap().project_data = Some(full_data);
        let display = serde_json::from_str::<serde_json::Value>(
            &queue.get_job_display_params(1).to_string(),
        )
        .expect("display params parse");
        assert_eq!(display["zoom_mode"].as_str(), Some("static"));
        assert!(display.get("smoothness").is_some());

        // Reference form ({"project_file": url}) carries no "stabilization" key —
        // display params must omit the stabilization-derived keys entirely instead
        // of fabricating zoom_mode="none"/smoothness=0.5/... (which used to leak
        // through the Simple-mode panel mirror into the main preview).
        queue.jobs.get_mut(&1).unwrap().project_data =
            Some(r#"{"project_file": "file:///D:/videos/DSC_0001.gyroflow"}"#.into());
        let display = serde_json::from_str::<serde_json::Value>(
            &queue.get_job_display_params(1).to_string(),
        )
        .expect("display params parse");
        for key in [
            "zoom_mode",
            "smoothness",
            "horizon_lock_amount",
            "lens_correction",
        ] {
            assert!(
                display.get(key).is_none(),
                "{key} must be absent for reference-form project_data"
            );
        }
        assert!(display.get("auto_rotate").is_some());
    }

