    // [gyro-drop-promotes-to-queue] Invariant: a single video import that carries no
    // device gyro file must stay on the untouched main-preview path. Implicit queueing was
    // explicitly rejected (see design Decision 3) because it would split `queueMode` and
    // silently disable the preview's auto-autosync.
    #[test]
    fn video_area_single_video_import_does_not_touch_the_queue() {
        let qml = include_str!("../ui/VideoArea.qml");
        let fn_idx = qml
            .find("function loadMultipleFiles")
            .expect("VideoArea.loadMultipleFiles exists");
        let remaining = &qml[fn_idx..];
        let next_fn_idx = remaining
            .find("function askForOutputLocation")
            .expect("loadMultipleFiles block end marker exists");
        let body = &remaining[..next_fn_idx];
        let single_idx = body
            .find("if (urls.length == 1)")
            .expect("VideoArea.loadMultipleFiles must keep single-item routing");
        let batch_idx = body
            .find("if (urls.length < 1) return;")
            .expect("loadMultipleFiles must keep its empty-input guard after single routing");
        let single_branch = &body[single_idx..batch_idx];

        assert_eq!(
            single_branch.matches("promotePreviewToQueue()").count(),
            1,
            "promotion must happen only in the *_mix.bin branch, never on the plain \
             single-video fallback"
        );
        assert_eq!(
            single_branch.matches("render_queue.add_gyro_file(").count(),
            1,
            "the single-item branch must register a gyro source only for *_mix.bin"
        );

        // Everything after the mix-bin branch (generic motion data + single video) must be
        // free of queue mutations.
        let mix_bin_end = single_branch
            .find("isSingleMotionDataFile(urls[0])")
            .expect("single-item routing must keep the generic motion-data check");
        let after_mix_bin = &single_branch[mix_bin_end..];
        for forbidden in [
            "promotePreviewToQueue()",
            "render_queue.add_gyro_file(",
            "render_queue.add(",
            "queue.item.shown = true",
        ] {
            assert!(
                !after_mix_bin.contains(forbidden),
                "the plain single-video / motion-data fallback must not touch the render \
                 queue (found {forbidden})"
            );
        }
    }

    // [gyro-drop-promotes-to-queue] Invariant: `queueMode` still means "panel visible AND
    // queue non-empty". This change must not create rows behind a closed panel, so the
    // predicate stays untouched; changing it would drag the whole stabilize/export
    // decision tree into this change's blast radius.
    #[test]
    fn app_queue_mode_predicate_still_requires_visible_panel() {
        let qml = include_str!("../ui/App.qml");

        assert_eq!(
            qml.matches("videoArea.queue.shown && render_queue.queue.rowCount() > 0")
                .count(),
            2,
            "runPluginStabilizeFlow and runStabilizedBatchExport must both keep the \
             visible-panel term in queueMode"
        );
        assert_eq!(
            qml.matches("videoArea.queue.shown && simpleExportBtnRow.queueRowCount > 0")
                .count(),
            2,
            "the bottom-bar enable/visibility bindings must keep the visible-panel term"
        );
    }

    // [queue-stuck-state-recovery] Invariant: recovery runs at the very top of
    // both Simple-mode flows, with the intent that matches the button, and
    // nowhere else. Position is load-bearing — every gate further down reads the
    // queue and would need a "skipped but should still count" special case if
    // recovery ran later. The intents must not be swapped either: "sync" lifts
    // plugin-only skips, "export" deliberately leaves them.
    #[test]
    fn stuck_state_recovery_runs_first_in_both_simple_mode_flows() {
        let qml = include_str!("../ui/App.qml");

        for (func, intent) in [
            ("function runPluginStabilizeFlow(): void {", "sync"),
            ("function runStabilizedBatchExport(): bool {", "export"),
        ] {
            let start = qml.find(func).unwrap_or_else(|| panic!("{func} exists"));
            // Bound the slice to this function: window-level functions sit at a
            // 4-space indent, so the next one marks the end.
            let after = &qml[start + func.len()..];
            let end = after.find("\n    function ").unwrap_or(after.len());
            let body = &after[..end];

            let call = format!("render_queue.revive_stuck_jobs(\"{intent}\")");
            let call_idx = body
                .find(&call)
                .unwrap_or_else(|| panic!("{func} must call {call}"));

            // Nothing that consults the queue's contents may run before recovery.
            // Tokens absent from this particular flow are simply not applicable.
            for later in [
                "hasGyroFiles",
                "batch_motion_ready()",
                "matchDirty",
                "syncDirty",
            ] {
                if let Some(later_idx) = body.find(later) {
                    assert!(
                        call_idx < later_idx,
                        "{func} must call revive_stuck_jobs before reading {later}"
                    );
                }
            }
        }

        assert_eq!(
            qml.matches("render_queue.revive_stuck_jobs(").count(),
            2,
            "recovery is scoped to the two Simple-mode buttons: no other entry \
             point (right-click Render now / Reset status / dialogs) may trigger it"
        );
    }

    // [queue-stuck-state-recovery] Invariant: every branch that can end a
    // dispatch without starting work and without opening a dialog must explain
    // itself. These two used to `return` in silence, which reads as a dead button.
    #[test]
    fn silent_dispatch_returns_are_explained() {
        let qml = include_str!("../ui/App.qml");

        assert!(
            qml.contains("function explainDispatchBlocked(intent: string): void {")
                && qml.contains("render_queue.dispatch_blocker_reason(intent)"),
            "App.qml must expose the shared blocked-dispatch explainer"
        );
        assert!(
            qml.contains(
                "if (!render_queue.batch_motion_ready()) { window.explainDispatchBlocked(\"sync\"); return; }"
            ),
            "the embedded-gyro stabilize branch must explain itself instead of returning silently"
        );
        assert!(
            qml.contains("window.explainDispatchBlocked(\"export\");"),
            "the export branch with no renderable job and no finished export must explain itself"
        );
        // The batch-sync entry point is the single choke point for its three
        // callers (syncDirty branch, re-export confirmation, post-match
        // continuation); guarding it there beats guarding each of them.
        let sync_fn = qml
            .find("function runSimpleBatchSync(): void {")
            .expect("runSimpleBatchSync exists");
        let sync_body = &qml[sync_fn..];
        let guard = sync_body
            .find("window.explainDispatchBlocked(\"sync\");")
            .expect("runSimpleBatchSync must explain a dispatch it cannot start");
        let dispatch = sync_body
            .find("render_queue.start_batch_autosync()")
            .expect("runSimpleBatchSync must dispatch");
        assert!(
            guard < dispatch,
            "the explanation must come before the dispatch, not after it"
        );
        // The re-export prompt must still win over the explainer.
        let export_idx = qml
            .find("if (render_queue.has_finished_video_exports())")
            .expect("the re-export branch must survive");
        let tail = &qml[export_idx..];
        let confirm_idx = tail.find("window.confirmReExport(\"video\");").unwrap();
        let explain_idx = tail.find("window.explainDispatchBlocked(\"export\");").unwrap();
        assert!(
            confirm_idx < explain_idx,
            "'already exported, re-export?' must take precedence over the blocked-dispatch notice"
        );
    }

    // [gyro-drop-promotes-to-queue] Invariant: the main preview's automatic autosync is
    // still gated on `editing_job_id == 0`. Single videos with embedded gyro (GoPro/Sony)
    // must keep auto-syncing on load exactly as before, because they are never promoted.
    #[test]
    fn synchronization_auto_autosync_still_gated_on_editing_job_id() {
        let qml = include_str!("../ui/menu/Synchronization.qml");
        assert!(
            qml.contains("render_queue.editing_job_id == 0"),
            "auto-autosync must stay disabled for queue jobs and enabled for plain \
             single-video imports"
        );
    }

    // [play-hint-after-deep-match] Invariant: the pending-stabilize flag is armed
    // at deep-match success and cleared at every batch-sync terminal state plus
    // the queue-clear cleanup. The clear sites are deliberately paired with the
    // `syncDirty = false` sites — a refactor that drops one silently leaves the
    // hint stuck on (or never shown), so pin the counts here.
    #[test]
    fn play_hint_flag_sites_stay_paired() {
        let rq = include_str!("../ui/RenderQueue.qml");
        assert_eq!(
            rq.matches("window.deepMatchStabilizePending = true").count(),
            1,
            "exactly one arming site: deep match success, next to matchDirty = true"
        );
        assert_eq!(
            rq.matches("window.deepMatchStabilizePending = false").count(),
            4,
            "three sync-settle sites (paired with syncDirty = false) plus the \
             queue-clear cleanup"
        );
        assert_eq!(
            rq.matches("window.syncDirty = false").count(),
            3,
            "sync-settle site count changed: mirror the change onto \
             deepMatchStabilizePending above"
        );
        let app = include_str!("../ui/App.qml");
        assert!(
            app.contains("property bool deepMatchStabilizePending: false"),
            "the window-level runtime flag must exist and default to false"
        );
        let va = include_str!("../ui/VideoArea.qml");
        assert!(
            va.contains("window.deepMatchStabilizePending")
                && va.contains("controller.stabilize_step_pending_for_preview()"),
            "the playback listener must gate on the flag AND the per-clip predicate"
        );
    }

